insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m2-test-r3','b2-m2-test',13,'multiple_choice','reading','{"prompt":"What does Paula still wish?","options":["That she earned more","That the bakery started later in the day","That she had stayed an engineer"],"answer":1,"passage":{"title":"If only I''d listened","text":"\"If only I''d listened to my grandmother,\" says Paula, a 34-year-old engineer who now runs a small bakery. \"She always told me that if I didn''t do something I loved, I would end up miserable, however much I earned.\" For years Paula ignored the advice. She had a well-paid job, a company car and almost no free time. \"I wish I had realised sooner that the money wasn''t making me happy,\" she admits. The turning point came during a long illness, when she started baking bread at home to pass the time. Friends began ordering loaves, then local cafés. Had she not been forced to stop working, she believes she would never have taken the risk. \"I''d rather earn less and wake up excited,\" she says. \"Although I do wish the bakery started a bit later than four a.m.!\""}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m3-test-r1','b2-m3-test',11,'multiple_choice','reading','{"prompt":"What happened to shops in Oslo and Pontevedra?","options":["Many closed","They became busier","They moved to the suburbs"],"answer":1,"passage":{"title":"Should we ban cars from city centres?","text":"Few urban policies divide opinion as sharply as banning cars from city centres. Supporters point to cities such as Oslo and Pontevedra, where pedestrianised streets have led to cleaner air, fewer accidents and, perhaps surprisingly, busier shops. Their argument is simple: streets designed for people attract people. Opponents, however, warn that bans can hit those who have no realistic alternative, such as elderly residents, people with disabilities or workers whose shifts start before public transport runs. Some shopkeepers also fear losing customers who drive in from the suburbs. On balance, the evidence suggests that bans work best when they are introduced gradually and accompanied by better buses, safe cycle lanes and exceptions for those who genuinely need a car. Imposed overnight, they are more likely to provoke a backlash than to change habits."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m3-test-r2','b2-m3-test',12,'multiple_choice','reading','{"prompt":"Who might be hurt by a ban, according to opponents?","options":["Tourists","People without a realistic alternative to the car","Cyclists"],"answer":1,"passage":{"title":"Should we ban cars from city centres?","text":"Few urban policies divide opinion as sharply as banning cars from city centres. Supporters point to cities such as Oslo and Pontevedra, where pedestrianised streets have led to cleaner air, fewer accidents and, perhaps surprisingly, busier shops. Their argument is simple: streets designed for people attract people. Opponents, however, warn that bans can hit those who have no realistic alternative, such as elderly residents, people with disabilities or workers whose shifts start before public transport runs. Some shopkeepers also fear losing customers who drive in from the suburbs. On balance, the evidence suggests that bans work best when they are introduced gradually and accompanied by better buses, safe cycle lanes and exceptions for those who genuinely need a car. Imposed overnight, they are more likely to provoke a backlash than to change habits."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m3-test-r3','b2-m3-test',13,'multiple_choice','reading','{"prompt":"What is the writer''s conclusion?","options":["Bans should be introduced overnight","Bans work best gradually and with alternatives","Bans never work"],"answer":1,"passage":{"title":"Should we ban cars from city centres?","text":"Few urban policies divide opinion as sharply as banning cars from city centres. Supporters point to cities such as Oslo and Pontevedra, where pedestrianised streets have led to cleaner air, fewer accidents and, perhaps surprisingly, busier shops. Their argument is simple: streets designed for people attract people. Opponents, however, warn that bans can hit those who have no realistic alternative, such as elderly residents, people with disabilities or workers whose shifts start before public transport runs. Some shopkeepers also fear losing customers who drive in from the suburbs. On balance, the evidence suggests that bans work best when they are introduced gradually and accompanied by better buses, safe cycle lanes and exceptions for those who genuinely need a car. Imposed overnight, they are more likely to provoke a backlash than to change habits."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m4-test-r1','b2-m4-test',11,'multiple_choice','reading','{"prompt":"How many units were affected in total?","options":["20","35","55"],"answer":2,"passage":{"title":"A formal complaint","text":"Dear Mr Hughes,\nI am writing to express my concern regarding the shipment we received on 3 March (order 4471). Of the 200 units ordered, 35 arrived damaged, and a further 20 were missing altogether. As a result, we were unable to fulfil two of our own client orders on time, which has caused us considerable inconvenience.\nWhile we appreciate that delays can occur, this is the second incident of this kind in three months. I would therefore be grateful if you could arrange a replacement of the damaged and missing items by the end of next week, and confirm what steps will be taken to prevent a recurrence.\nShould the situation not be resolved, we may need to reconsider our agreement. I look forward to your prompt reply.\nYours sincerely,\nAna Ribeiro\nPurchasing Manager"}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m4-test-r2','b2-m4-test',12,'multiple_choice','reading','{"prompt":"Why is Ana particularly concerned?","options":["It''s the second similar incident in three months","The price went up","The order was cancelled"],"answer":0,"passage":{"title":"A formal complaint","text":"Dear Mr Hughes,\nI am writing to express my concern regarding the shipment we received on 3 March (order 4471). Of the 200 units ordered, 35 arrived damaged, and a further 20 were missing altogether. As a result, we were unable to fulfil two of our own client orders on time, which has caused us considerable inconvenience.\nWhile we appreciate that delays can occur, this is the second incident of this kind in three months. I would therefore be grateful if you could arrange a replacement of the damaged and missing items by the end of next week, and confirm what steps will be taken to prevent a recurrence.\nShould the situation not be resolved, we may need to reconsider our agreement. I look forward to your prompt reply.\nYours sincerely,\nAna Ribeiro\nPurchasing Manager"}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m4-test-r3','b2-m4-test',13,'multiple_choice','reading','{"prompt":"What does ''reconsider our agreement'' suggest?","options":["They want a discount","They might end the business relationship","They want to order more"],"answer":1,"passage":{"title":"A formal complaint","text":"Dear Mr Hughes,\nI am writing to express my concern regarding the shipment we received on 3 March (order 4471). Of the 200 units ordered, 35 arrived damaged, and a further 20 were missing altogether. As a result, we were unable to fulfil two of our own client orders on time, which has caused us considerable inconvenience.\nWhile we appreciate that delays can occur, this is the second incident of this kind in three months. I would therefore be grateful if you could arrange a replacement of the damaged and missing items by the end of next week, and confirm what steps will be taken to prevent a recurrence.\nShould the situation not be resolved, we may need to reconsider our agreement. I look forward to your prompt reply.\nYours sincerely,\nAna Ribeiro\nPurchasing Manager"}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m5-test-r1','b2-m5-test',11,'multiple_choice','reading','{"prompt":"What did ''nice'' originally mean?","options":["Pleasant","Foolish or ignorant","Beautiful"],"answer":1,"passage":{"title":"Words that changed meaning","text":"Language never stands still, and some everyday English words have travelled a surprisingly long way from their original meanings. ''Nice'', for instance, once meant ''foolish'' or ''ignorant''; it only came to mean ''pleasant'' in the eighteenth century. ''Awful'' used to mean ''full of awe'', that is, deeply impressive, before it drifted towards ''terrible''. More recently, ''literally'' has been widely used to mean its exact opposite, as in ''I literally died laughing'', which annoys many careful speakers but is now recorded in major dictionaries. Linguists generally avoid calling these changes mistakes. Instead, they see them as evidence that meaning is shaped by use: if enough people use a word in a new way for long enough, the new sense becomes part of the language, whether or not we approve."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m5-test-r2','b2-m5-test',12,'multiple_choice','reading','{"prompt":"Why do some speakers dislike the modern use of ''literally''?","options":["It''s too formal","It is used to mean the opposite of its exact meaning","It''s an American word"],"answer":1,"passage":{"title":"Words that changed meaning","text":"Language never stands still, and some everyday English words have travelled a surprisingly long way from their original meanings. ''Nice'', for instance, once meant ''foolish'' or ''ignorant''; it only came to mean ''pleasant'' in the eighteenth century. ''Awful'' used to mean ''full of awe'', that is, deeply impressive, before it drifted towards ''terrible''. More recently, ''literally'' has been widely used to mean its exact opposite, as in ''I literally died laughing'', which annoys many careful speakers but is now recorded in major dictionaries. Linguists generally avoid calling these changes mistakes. Instead, they see them as evidence that meaning is shaped by use: if enough people use a word in a new way for long enough, the new sense becomes part of the language, whether or not we approve."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m5-test-r3','b2-m5-test',13,'multiple_choice','reading','{"prompt":"What is the linguists'' view?","options":["These changes are mistakes","Meaning is shaped by use","Dictionaries should not record new meanings"],"answer":1,"passage":{"title":"Words that changed meaning","text":"Language never stands still, and some everyday English words have travelled a surprisingly long way from their original meanings. ''Nice'', for instance, once meant ''foolish'' or ''ignorant''; it only came to mean ''pleasant'' in the eighteenth century. ''Awful'' used to mean ''full of awe'', that is, deeply impressive, before it drifted towards ''terrible''. More recently, ''literally'' has been widely used to mean its exact opposite, as in ''I literally died laughing'', which annoys many careful speakers but is now recorded in major dictionaries. Linguists generally avoid calling these changes mistakes. Instead, they see them as evidence that meaning is shaped by use: if enough people use a word in a new way for long enough, the new sense becomes part of the language, whether or not we approve."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m6-test-r1','b2-m6-test',11,'multiple_choice','reading','{"prompt":"What does the original research often show?","options":["Something more modest than the headline","Exactly what the headline says","Nothing at all"],"answer":0,"passage":{"title":"How to spot misleading headlines","text":"A headline claiming that ''coffee doubles your risk of disease'' will be shared thousands of times before anyone reads the study behind it. Often, the research shows something far more modest: perhaps a small increase in risk, found in a limited group, that may not be caused by coffee at all. Before sharing a dramatic story, it is worth asking a few questions. Who published it, and do they have an obvious interest in the result? Does the article link to the original source? Is a correlation being presented as if it were a cause? And are the numbers relative or absolute? A risk that ''doubles'' from one in a million to two in a million sounds alarming but is, in practical terms, tiny. None of this requires expert knowledge, just the habit of slowing down before clicking ''share''."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m6-test-r2','b2-m6-test',12,'multiple_choice','reading','{"prompt":"Why can ''doubles your risk'' be misleading?","options":["The relative increase may be tiny in absolute terms","Studies are always wrong","Coffee is healthy"],"answer":0,"passage":{"title":"How to spot misleading headlines","text":"A headline claiming that ''coffee doubles your risk of disease'' will be shared thousands of times before anyone reads the study behind it. Often, the research shows something far more modest: perhaps a small increase in risk, found in a limited group, that may not be caused by coffee at all. Before sharing a dramatic story, it is worth asking a few questions. Who published it, and do they have an obvious interest in the result? Does the article link to the original source? Is a correlation being presented as if it were a cause? And are the numbers relative or absolute? A risk that ''doubles'' from one in a million to two in a million sounds alarming but is, in practical terms, tiny. None of this requires expert knowledge, just the habit of slowing down before clicking ''share''."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m6-test-r3','b2-m6-test',13,'multiple_choice','reading','{"prompt":"What is the writer''s main advice?","options":["Only read scientific journals","Slow down and check before sharing","Never share news"],"answer":1,"passage":{"title":"How to spot misleading headlines","text":"A headline claiming that ''coffee doubles your risk of disease'' will be shared thousands of times before anyone reads the study behind it. Often, the research shows something far more modest: perhaps a small increase in risk, found in a limited group, that may not be caused by coffee at all. Before sharing a dramatic story, it is worth asking a few questions. Who published it, and do they have an obvious interest in the result? Does the article link to the original source? Is a correlation being presented as if it were a cause? And are the numbers relative or absolute? A risk that ''doubles'' from one in a million to two in a million sounds alarming but is, in practical terms, tiny. None of this requires expert knowledge, just the habit of slowing down before clicking ''share''."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m7-test-r1','b2-m7-test',11,'multiple_choice','reading','{"prompt":"What is usually the main problem in understanding native speakers?","options":["Vocabulary","Connected speech and natural features of conversation","Grammar"],"answer":1,"passage":{"title":"Why native speakers are hard to understand","text":"Many learners who read English comfortably are shocked the first time they try to follow a conversation between native speakers. The problem is rarely vocabulary. In connected speech, words blend together: ''what do you want to do?'' can sound like ''whaddaya wanna do?'', and weak forms such as ''to'', ''for'' and ''of'' almost disappear. Speakers also overlap, change topic halfway through a sentence and use fillers like ''you know'' and ''sort of''. Textbook recordings, by contrast, tend to be slow, clear and perfectly polite. The good news is that the ear can be trained. Listening regularly to authentic material slightly above your level, first without and then with a transcript, helps the brain recognise these patterns. Shadowing, repeating what you hear almost at the same time, is particularly effective, because producing the sounds makes them easier to perceive."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m7-test-r2','b2-m7-test',12,'multiple_choice','reading','{"prompt":"How are textbook recordings described?","options":["Fast and natural","Slow, clear and polite","Full of slang"],"answer":1,"passage":{"title":"Why native speakers are hard to understand","text":"Many learners who read English comfortably are shocked the first time they try to follow a conversation between native speakers. The problem is rarely vocabulary. In connected speech, words blend together: ''what do you want to do?'' can sound like ''whaddaya wanna do?'', and weak forms such as ''to'', ''for'' and ''of'' almost disappear. Speakers also overlap, change topic halfway through a sentence and use fillers like ''you know'' and ''sort of''. Textbook recordings, by contrast, tend to be slow, clear and perfectly polite. The good news is that the ear can be trained. Listening regularly to authentic material slightly above your level, first without and then with a transcript, helps the brain recognise these patterns. Shadowing, repeating what you hear almost at the same time, is particularly effective, because producing the sounds makes them easier to perceive."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m7-test-r3','b2-m7-test',13,'multiple_choice','reading','{"prompt":"Why is shadowing effective, according to the text?","options":["It''s fun","Producing the sounds makes them easier to perceive","It improves grammar"],"answer":1,"passage":{"title":"Why native speakers are hard to understand","text":"Many learners who read English comfortably are shocked the first time they try to follow a conversation between native speakers. The problem is rarely vocabulary. In connected speech, words blend together: ''what do you want to do?'' can sound like ''whaddaya wanna do?'', and weak forms such as ''to'', ''for'' and ''of'' almost disappear. Speakers also overlap, change topic halfway through a sentence and use fillers like ''you know'' and ''sort of''. Textbook recordings, by contrast, tend to be slow, clear and perfectly polite. The good news is that the ear can be trained. Listening regularly to authentic material slightly above your level, first without and then with a transcript, helps the brain recognise these patterns. Shadowing, repeating what you hear almost at the same time, is particularly effective, because producing the sounds makes them easier to perceive."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m8-test-r1','b2-m8-test',11,'multiple_choice','reading','{"prompt":"What do audiences remember most?","options":["The data","The story the speaker tells","The number of slides"],"answer":1,"passage":{"title":"What really makes a good presentation","text":"What audiences remember is rarely the data on the slides; it is the story the speaker tells about it. It is clarity, not complexity, that persuades. Never have so many people had access to presentation software, yet rarely have presentations been so forgettable: forty slides of bullet points, read aloud word for word. The best speakers do the opposite. What they do first is decide the one message the audience should leave with, and only then choose the evidence that supports it. Only after that do they think about slides, and when they do, they use few words and plenty of images. Above all, they rehearse. Not until you have said your talk out loud several times will you discover where it drags, where an example is missing, or where you simply don''t know what comes next."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m8-test-r2','b2-m8-test',12,'multiple_choice','reading','{"prompt":"What do the best speakers decide first?","options":["The slide design","The one message for the audience","The length of the talk"],"answer":1,"passage":{"title":"What really makes a good presentation","text":"What audiences remember is rarely the data on the slides; it is the story the speaker tells about it. It is clarity, not complexity, that persuades. Never have so many people had access to presentation software, yet rarely have presentations been so forgettable: forty slides of bullet points, read aloud word for word. The best speakers do the opposite. What they do first is decide the one message the audience should leave with, and only then choose the evidence that supports it. Only after that do they think about slides, and when they do, they use few words and plenty of images. Above all, they rehearse. Not until you have said your talk out loud several times will you discover where it drags, where an example is missing, or where you simply don''t know what comes next."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m8-test-r3','b2-m8-test',13,'multiple_choice','reading','{"prompt":"Why is rehearsing out loud important?","options":["To memorise every word","To discover weak points in the talk","To use more slides"],"answer":1,"passage":{"title":"What really makes a good presentation","text":"What audiences remember is rarely the data on the slides; it is the story the speaker tells about it. It is clarity, not complexity, that persuades. Never have so many people had access to presentation software, yet rarely have presentations been so forgettable: forty slides of bullet points, read aloud word for word. The best speakers do the opposite. What they do first is decide the one message the audience should leave with, and only then choose the evidence that supports it. Only after that do they think about slides, and when they do, they use few words and plenty of images. Above all, they rehearse. Not until you have said your talk out loud several times will you discover where it drags, where an example is missing, or where you simply don''t know what comes next."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m1-test-r1','c1-m1-test',11,'multiple_choice','reading','{"prompt":"What is ''multitasking'' mostly, according to research?","options":["Doing two things at exactly the same time","Rapid switching between tasks","A rare talent"],"answer":1,"passage":{"title":"The myth of multitasking","text":"It is widely assumed that the ability to juggle several tasks at once is a hallmark of efficiency. Were this true, the constant stream of notifications that punctuates the modern working day would be making us more productive, not less. Research consistently suggests otherwise. What we call multitasking is, for the most part, rapid task-switching, and each switch carries a cognitive cost: attention lingers on the previous task, errors creep in and complex work takes noticeably longer. Not only does performance suffer, but people who multitask heavily also tend to overestimate how well they are doing. That said, the picture is not entirely bleak. Routine activities that require little conscious thought, such as walking while talking, can be combined without much loss. The difficulty arises when two demanding tasks compete for the same limited resource: our attention."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m1-test-r2','c1-m1-test',12,'multiple_choice','reading','{"prompt":"What is surprising about heavy multitaskers?","options":["They are more creative","They overestimate their performance","They work fewer hours"],"answer":1,"passage":{"title":"The myth of multitasking","text":"It is widely assumed that the ability to juggle several tasks at once is a hallmark of efficiency. Were this true, the constant stream of notifications that punctuates the modern working day would be making us more productive, not less. Research consistently suggests otherwise. What we call multitasking is, for the most part, rapid task-switching, and each switch carries a cognitive cost: attention lingers on the previous task, errors creep in and complex work takes noticeably longer. Not only does performance suffer, but people who multitask heavily also tend to overestimate how well they are doing. That said, the picture is not entirely bleak. Routine activities that require little conscious thought, such as walking while talking, can be combined without much loss. The difficulty arises when two demanding tasks compete for the same limited resource: our attention."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m1-test-r3','c1-m1-test',13,'multiple_choice','reading','{"prompt":"When can tasks be combined without much loss?","options":["When both are demanding","When one is routine and needs little conscious thought","Never"],"answer":1,"passage":{"title":"The myth of multitasking","text":"It is widely assumed that the ability to juggle several tasks at once is a hallmark of efficiency. Were this true, the constant stream of notifications that punctuates the modern working day would be making us more productive, not less. Research consistently suggests otherwise. What we call multitasking is, for the most part, rapid task-switching, and each switch carries a cognitive cost: attention lingers on the previous task, errors creep in and complex work takes noticeably longer. Not only does performance suffer, but people who multitask heavily also tend to overestimate how well they are doing. That said, the picture is not entirely bleak. Routine activities that require little conscious thought, such as walking while talking, can be combined without much loss. The difficulty arises when two demanding tasks compete for the same limited resource: our attention."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m2-test-r1','c1-m2-test',11,'multiple_choice','reading','{"prompt":"What was the main overall finding?","options":["Online learning increased motivation","Overall motivation did not differ significantly between formats","Face-to-face was clearly better"],"answer":1,"passage":{"title":"Abstract: remote learning and motivation","text":"This study examines the relationship between remote learning formats and student motivation among 1,240 undergraduate students across four universities. Participants completed a validated motivation questionnaire at the beginning and end of a twelve-week term in one of three formats: fully online, blended, or face-to-face. Contrary to our initial hypothesis, overall motivation did not differ significantly between formats. However, a closer analysis revealed a marked interaction with prior academic performance: students with lower entry grades reported a substantial decline in motivation in the fully online format, whereas high-achieving students were largely unaffected. These findings suggest that the debate over online versus in-person teaching may be framed too broadly. Rather than asking which format is superior, institutions might more usefully ask which students require additional structure and support when teaching moves online."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m2-test-r2','c1-m2-test',12,'multiple_choice','reading','{"prompt":"Which students lost motivation online?","options":["High achievers","Students with lower entry grades","All first-year students"],"answer":1,"passage":{"title":"Abstract: remote learning and motivation","text":"This study examines the relationship between remote learning formats and student motivation among 1,240 undergraduate students across four universities. Participants completed a validated motivation questionnaire at the beginning and end of a twelve-week term in one of three formats: fully online, blended, or face-to-face. Contrary to our initial hypothesis, overall motivation did not differ significantly between formats. However, a closer analysis revealed a marked interaction with prior academic performance: students with lower entry grades reported a substantial decline in motivation in the fully online format, whereas high-achieving students were largely unaffected. These findings suggest that the debate over online versus in-person teaching may be framed too broadly. Rather than asking which format is superior, institutions might more usefully ask which students require additional structure and support when teaching moves online."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m2-test-r3','c1-m2-test',13,'multiple_choice','reading','{"prompt":"What do the authors recommend?","options":["Ending online teaching","Asking which students need more support online","Using only blended formats"],"answer":1,"passage":{"title":"Abstract: remote learning and motivation","text":"This study examines the relationship between remote learning formats and student motivation among 1,240 undergraduate students across four universities. Participants completed a validated motivation questionnaire at the beginning and end of a twelve-week term in one of three formats: fully online, blended, or face-to-face. Contrary to our initial hypothesis, overall motivation did not differ significantly between formats. However, a closer analysis revealed a marked interaction with prior academic performance: students with lower entry grades reported a substantial decline in motivation in the fully online format, whereas high-achieving students were largely unaffected. These findings suggest that the debate over online versus in-person teaching may be framed too broadly. Rather than asking which format is superior, institutions might more usefully ask which students require additional structure and support when teaching moves online."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m3-test-r1','c1-m3-test',11,'multiple_choice','reading','{"prompt":"How do critics usually describe the four-day week?","options":["As a luxury businesses can''t afford","As the future of work","As illegal"],"answer":0,"passage":{"title":"The case for a four-day week","text":"Critics of the four-day working week tend to frame it as a luxury: an appealing idea, perhaps, but one that businesses can ill afford. The evidence from recent trials points in a rather different direction. In pilot schemes involving dozens of companies, productivity was largely maintained, sick days fell and staff turnover dropped, which, given the cost of recruiting and training replacements, is no small saving. Admittedly, the model is not universally applicable. Hospitals, schools and other services that depend on continuous cover cannot simply close on Fridays, and some firms found that a compressed week merely crammed the same stress into fewer days. Yet the question is not whether every organisation should adopt it tomorrow, but whether we are prepared to rethink a five-day structure that was designed for factories a century ago. Dismissing the idea out of hand seems, at the very least, premature."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m3-test-r2','c1-m3-test',12,'multiple_choice','reading','{"prompt":"Which result of the trials is presented as a significant saving?","options":["Lower salaries","Reduced staff turnover","Smaller offices"],"answer":1,"passage":{"title":"The case for a four-day week","text":"Critics of the four-day working week tend to frame it as a luxury: an appealing idea, perhaps, but one that businesses can ill afford. The evidence from recent trials points in a rather different direction. In pilot schemes involving dozens of companies, productivity was largely maintained, sick days fell and staff turnover dropped, which, given the cost of recruiting and training replacements, is no small saving. Admittedly, the model is not universally applicable. Hospitals, schools and other services that depend on continuous cover cannot simply close on Fridays, and some firms found that a compressed week merely crammed the same stress into fewer days. Yet the question is not whether every organisation should adopt it tomorrow, but whether we are prepared to rethink a five-day structure that was designed for factories a century ago. Dismissing the idea out of hand seems, at the very least, premature."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m3-test-r3','c1-m3-test',13,'multiple_choice','reading','{"prompt":"What is the writer''s position?","options":["Every company should adopt it immediately","Rejecting the idea without consideration is premature","The five-day week is perfect"],"answer":1,"passage":{"title":"The case for a four-day week","text":"Critics of the four-day working week tend to frame it as a luxury: an appealing idea, perhaps, but one that businesses can ill afford. The evidence from recent trials points in a rather different direction. In pilot schemes involving dozens of companies, productivity was largely maintained, sick days fell and staff turnover dropped, which, given the cost of recruiting and training replacements, is no small saving. Admittedly, the model is not universally applicable. Hospitals, schools and other services that depend on continuous cover cannot simply close on Fridays, and some firms found that a compressed week merely crammed the same stress into fewer days. Yet the question is not whether every organisation should adopt it tomorrow, but whether we are prepared to rethink a five-day structure that was designed for factories a century ago. Dismissing the idea out of hand seems, at the very least, premature."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m4-test-r1','c1-m4-test',11,'multiple_choice','reading','{"prompt":"Which word for having little body fat is described as complimentary?","options":["Thin","Slim","Skinny"],"answer":1,"passage":{"title":"Nuance in everyday words","text":"Advanced learners often discover that words they considered synonyms are anything but. ''Thin'', ''slim'' and ''skinny'' all describe someone with little body fat, yet ''slim'' is complimentary, ''thin'' is neutral or slightly worrying, and ''skinny'' can sound critical or, in fashion, simply descriptive. Similarly, ''stubborn'' and ''determined'' may describe exactly the same behaviour; the choice reveals whether the speaker approves of it. Collocation matters too: we say ''heavy rain'' but ''strong wind'', ''make a decision'' but ''do your homework'', and a ''tall building'' but a ''high mountain''. None of these combinations is logical, which is precisely why they mark a speaker as fluent. Rather than memorising lists, the most efficient strategy is to notice words in context and record the phrases they typically appear in, not just their dictionary definitions."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m4-test-r2','c1-m4-test',12,'multiple_choice','reading','{"prompt":"What does choosing ''stubborn'' instead of ''determined'' reveal?","options":["The speaker''s approval or disapproval","The person''s age","Formality"],"answer":0,"passage":{"title":"Nuance in everyday words","text":"Advanced learners often discover that words they considered synonyms are anything but. ''Thin'', ''slim'' and ''skinny'' all describe someone with little body fat, yet ''slim'' is complimentary, ''thin'' is neutral or slightly worrying, and ''skinny'' can sound critical or, in fashion, simply descriptive. Similarly, ''stubborn'' and ''determined'' may describe exactly the same behaviour; the choice reveals whether the speaker approves of it. Collocation matters too: we say ''heavy rain'' but ''strong wind'', ''make a decision'' but ''do your homework'', and a ''tall building'' but a ''high mountain''. None of these combinations is logical, which is precisely why they mark a speaker as fluent. Rather than memorising lists, the most efficient strategy is to notice words in context and record the phrases they typically appear in, not just their dictionary definitions."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m4-test-r3','c1-m4-test',13,'multiple_choice','reading','{"prompt":"What strategy does the writer recommend?","options":["Memorising synonym lists","Noticing words in context and recording typical phrases","Using a thesaurus"],"answer":1,"passage":{"title":"Nuance in everyday words","text":"Advanced learners often discover that words they considered synonyms are anything but. ''Thin'', ''slim'' and ''skinny'' all describe someone with little body fat, yet ''slim'' is complimentary, ''thin'' is neutral or slightly worrying, and ''skinny'' can sound critical or, in fashion, simply descriptive. Similarly, ''stubborn'' and ''determined'' may describe exactly the same behaviour; the choice reveals whether the speaker approves of it. Collocation matters too: we say ''heavy rain'' but ''strong wind'', ''make a decision'' but ''do your homework'', and a ''tall building'' but a ''high mountain''. None of these combinations is logical, which is precisely why they mark a speaker as fluent. Rather than memorising lists, the most efficient strategy is to notice words in context and record the phrases they typically appear in, not just their dictionary definitions."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m5-test-r1','c1-m5-test',11,'multiple_choice','reading','{"prompt":"Why is the team being restructured?","options":["To cut jobs","To reduce resolution times and build expertise","To move offices"],"answer":1,"passage":{"title":"Memo: restructuring the support team","text":"To: All Customer Support Staff\nFrom: Operations Director\nRe: Changes to team structure\nFollowing a review of last year''s performance, we will be restructuring the support function with effect from 1 June. Rather than handling all enquiries in a single queue, the team will be divided into two specialist groups: one dedicated to technical issues and the other to billing and accounts. The aim is to reduce average resolution times, which rose by 18% last year, and to give staff the opportunity to develop deeper expertise.\nWe recognise that change of this kind can be unsettling. Let me stress that no roles will be lost as a result of the restructuring. Team leaders will meet each member of staff individually over the coming fortnight to discuss preferences, and every effort will be made to accommodate them. Training for both groups will begin in mid-May."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m5-test-r2','c1-m5-test',12,'multiple_choice','reading','{"prompt":"What reassurance does the memo give?","options":["Salaries will rise","No roles will be lost","Training is optional"],"answer":1,"passage":{"title":"Memo: restructuring the support team","text":"To: All Customer Support Staff\nFrom: Operations Director\nRe: Changes to team structure\nFollowing a review of last year''s performance, we will be restructuring the support function with effect from 1 June. Rather than handling all enquiries in a single queue, the team will be divided into two specialist groups: one dedicated to technical issues and the other to billing and accounts. The aim is to reduce average resolution times, which rose by 18% last year, and to give staff the opportunity to develop deeper expertise.\nWe recognise that change of this kind can be unsettling. Let me stress that no roles will be lost as a result of the restructuring. Team leaders will meet each member of staff individually over the coming fortnight to discuss preferences, and every effort will be made to accommodate them. Training for both groups will begin in mid-May."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m5-test-r3','c1-m5-test',13,'multiple_choice','reading','{"prompt":"What will happen over the next two weeks?","options":["Team leaders will meet each staff member individually","Training will start","The new structure will begin"],"answer":0,"passage":{"title":"Memo: restructuring the support team","text":"To: All Customer Support Staff\nFrom: Operations Director\nRe: Changes to team structure\nFollowing a review of last year''s performance, we will be restructuring the support function with effect from 1 June. Rather than handling all enquiries in a single queue, the team will be divided into two specialist groups: one dedicated to technical issues and the other to billing and accounts. The aim is to reduce average resolution times, which rose by 18% last year, and to give staff the opportunity to develop deeper expertise.\nWe recognise that change of this kind can be unsettling. Let me stress that no roles will be lost as a result of the restructuring. Team leaders will meet each member of staff individually over the coming fortnight to discuss preferences, and every effort will be made to accommodate them. Training for both groups will begin in mid-May."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m6-test-r1','c1-m6-test',11,'multiple_choice','reading','{"prompt":"What does the reader realise halfway through?","options":["The narrator may not be reliable","The storm never happened","The book is a comedy"],"answer":0,"passage":{"title":"Review: a novel that refuses easy answers","text":"There is a moment, roughly halfway through ''The Quiet Harbour'', when the reader realises that the narrator cannot be entirely trusted. It is handled so deftly that one is tempted to go back to the beginning and reread every conversation in a new light. This is a novel that resists easy answers: the central mystery, what really happened on the night of the storm, is never fully resolved, and readers who demand neat endings may find this frustrating. Others will see it as the book''s greatest strength. The prose is restrained, occasionally to a fault; there are passages in the second half where the tension slackens and the author''s fondness for description slows things to a crawl. Even so, it is a remarkably assured debut, and one whose characters linger in the mind long after the final page."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m6-test-r2','c1-m6-test',12,'multiple_choice','reading','{"prompt":"Which readers might be frustrated?","options":["Those who like long descriptions","Those who want neat, resolved endings","Those who dislike mysteries"],"answer":1,"passage":{"title":"Review: a novel that refuses easy answers","text":"There is a moment, roughly halfway through ''The Quiet Harbour'', when the reader realises that the narrator cannot be entirely trusted. It is handled so deftly that one is tempted to go back to the beginning and reread every conversation in a new light. This is a novel that resists easy answers: the central mystery, what really happened on the night of the storm, is never fully resolved, and readers who demand neat endings may find this frustrating. Others will see it as the book''s greatest strength. The prose is restrained, occasionally to a fault; there are passages in the second half where the tension slackens and the author''s fondness for description slows things to a crawl. Even so, it is a remarkably assured debut, and one whose characters linger in the mind long after the final page."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m6-test-r3','c1-m6-test',13,'multiple_choice','reading','{"prompt":"What does ''restrained, occasionally to a fault'' imply?","options":["The writing is always perfect","The style is controlled but sometimes too much so","The book is too short"],"answer":1,"passage":{"title":"Review: a novel that refuses easy answers","text":"There is a moment, roughly halfway through ''The Quiet Harbour'', when the reader realises that the narrator cannot be entirely trusted. It is handled so deftly that one is tempted to go back to the beginning and reread every conversation in a new light. This is a novel that resists easy answers: the central mystery, what really happened on the night of the storm, is never fully resolved, and readers who demand neat endings may find this frustrating. Others will see it as the book''s greatest strength. The prose is restrained, occasionally to a fault; there are passages in the second half where the tension slackens and the author''s fondness for description slows things to a crawl. Even so, it is a remarkably assured debut, and one whose characters linger in the mind long after the final page."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m7-test-r1','c1-m7-test',11,'multiple_choice','reading','{"prompt":"Which group is surprisingly affected by loneliness?","options":["The elderly","Young adults","Parents"],"answer":1,"passage":{"title":"The loneliness paradox","text":"We have never been more connected, yet surveys across several countries suggest that loneliness is on the rise, particularly among young adults, a group long assumed to be the most socially active. The obvious culprit is social media, and there is some evidence that passive scrolling, comparing one''s own life with curated highlights of others'', leaves people feeling worse. But the explanation is probably more complex. Work has become more mobile, people move cities more often, and the informal places where communities once formed, clubs, local pubs, places of worship, have declined. Loneliness, researchers stress, is not the same as being alone: it is the gap between the relationships we have and those we want. Tackling it may therefore depend less on limiting screen time than on rebuilding everyday spaces where people can meet without needing a reason."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m7-test-r2','c1-m7-test',12,'multiple_choice','reading','{"prompt":"How do researchers define loneliness?","options":["Spending time alone","The gap between the relationships we have and those we want","Using social media too much"],"answer":1,"passage":{"title":"The loneliness paradox","text":"We have never been more connected, yet surveys across several countries suggest that loneliness is on the rise, particularly among young adults, a group long assumed to be the most socially active. The obvious culprit is social media, and there is some evidence that passive scrolling, comparing one''s own life with curated highlights of others'', leaves people feeling worse. But the explanation is probably more complex. Work has become more mobile, people move cities more often, and the informal places where communities once formed, clubs, local pubs, places of worship, have declined. Loneliness, researchers stress, is not the same as being alone: it is the gap between the relationships we have and those we want. Tackling it may therefore depend less on limiting screen time than on rebuilding everyday spaces where people can meet without needing a reason."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m7-test-r3','c1-m7-test',13,'multiple_choice','reading','{"prompt":"What solution does the writer favour?","options":["Banning social media","Rebuilding everyday spaces where people can meet","Working from home"],"answer":1,"passage":{"title":"The loneliness paradox","text":"We have never been more connected, yet surveys across several countries suggest that loneliness is on the rise, particularly among young adults, a group long assumed to be the most socially active. The obvious culprit is social media, and there is some evidence that passive scrolling, comparing one''s own life with curated highlights of others'', leaves people feeling worse. But the explanation is probably more complex. Work has become more mobile, people move cities more often, and the informal places where communities once formed, clubs, local pubs, places of worship, have declined. Loneliness, researchers stress, is not the same as being alone: it is the gap between the relationships we have and those we want. Tackling it may therefore depend less on limiting screen time than on rebuilding everyday spaces where people can meet without needing a reason."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m8-test-r1','c1-m8-test',11,'multiple_choice','reading','{"prompt":"Why might people sound ''flatter'' in a second language?","options":["They speak correctly rather than personally","They don''t know grammar","They speak too fast"],"answer":0,"passage":{"title":"Finding your voice in a second language","text":"Many proficient speakers report feeling like a slightly different person in their second language: more formal, perhaps, or less funny, or oddly more direct. This is not merely imagination. Humour, irony and small talk rely heavily on shared cultural references and on the confidence to play with language, and both take time to develop. For a while, the safest strategy is to speak correctly rather than personally, which can make us sound flatter than we are. The way forward is not to imitate native speakers wholesale but to notice the expressions that fit our own personality and gradually make them ours. Someone who is naturally understated might adopt ''not bad at all'' rather than ''amazing''; someone who loves wordplay might start collecting idioms to twist. Fluency, in the end, is less about sounding native than about sounding like yourself."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m8-test-r2','c1-m8-test',12,'multiple_choice','reading','{"prompt":"What does the writer recommend?","options":["Imitating native speakers completely","Adopting expressions that fit your own personality","Avoiding humour"],"answer":1,"passage":{"title":"Finding your voice in a second language","text":"Many proficient speakers report feeling like a slightly different person in their second language: more formal, perhaps, or less funny, or oddly more direct. This is not merely imagination. Humour, irony and small talk rely heavily on shared cultural references and on the confidence to play with language, and both take time to develop. For a while, the safest strategy is to speak correctly rather than personally, which can make us sound flatter than we are. The way forward is not to imitate native speakers wholesale but to notice the expressions that fit our own personality and gradually make them ours. Someone who is naturally understated might adopt ''not bad at all'' rather than ''amazing''; someone who loves wordplay might start collecting idioms to twist. Fluency, in the end, is less about sounding native than about sounding like yourself."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m8-test-r3','c1-m8-test',13,'multiple_choice','reading','{"prompt":"What is fluency ultimately about, according to the text?","options":["Sounding native","Sounding like yourself","Knowing many idioms"],"answer":1,"passage":{"title":"Finding your voice in a second language","text":"Many proficient speakers report feeling like a slightly different person in their second language: more formal, perhaps, or less funny, or oddly more direct. This is not merely imagination. Humour, irony and small talk rely heavily on shared cultural references and on the confidence to play with language, and both take time to develop. For a while, the safest strategy is to speak correctly rather than personally, which can make us sound flatter than we are. The way forward is not to imitate native speakers wholesale but to notice the expressions that fit our own personality and gradually make them ours. Someone who is naturally understated might adopt ''not bad at all'' rather than ''amazing''; someone who loves wordplay might start collecting idioms to twist. Fluency, in the end, is less about sounding native than about sounding like yourself."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m1-test-r1','c2-m1-test',11,'multiple_choice','reading','{"prompt":"How does science advance, according to the writer?","options":["By confirming existing beliefs","By discovering that theories don''t survive the evidence","By avoiding mistakes"],"answer":1,"passage":{"title":"On the virtues of being wrong","text":"Seldom do we celebrate being wrong, and yet it is arguably the only route by which anyone has ever learnt anything. Science advances not by confirming what it already believes but by discovering, often to the considerable embarrassment of those concerned, that cherished theories do not survive contact with the evidence. Were individuals to adopt the same attitude, much needless conflict might be avoided. The difficulty is that being wrong rarely feels like anything at all until the moment we realise it; up to that point, it feels exactly like being right. Hence the peculiar confidence with which people defend positions they would, given more information, abandon without a second thought. Cultivating intellectual humility, then, is not a matter of doubting everything, which would be paralysing, but of holding one''s views with a grip firm enough to act on and loose enough to revise."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m1-test-r2','c2-m1-test',12,'multiple_choice','reading','{"prompt":"Why do people defend wrong positions so confidently?","options":["Being wrong feels exactly like being right until we realise it","They enjoy arguing","They lack education"],"answer":0,"passage":{"title":"On the virtues of being wrong","text":"Seldom do we celebrate being wrong, and yet it is arguably the only route by which anyone has ever learnt anything. Science advances not by confirming what it already believes but by discovering, often to the considerable embarrassment of those concerned, that cherished theories do not survive contact with the evidence. Were individuals to adopt the same attitude, much needless conflict might be avoided. The difficulty is that being wrong rarely feels like anything at all until the moment we realise it; up to that point, it feels exactly like being right. Hence the peculiar confidence with which people defend positions they would, given more information, abandon without a second thought. Cultivating intellectual humility, then, is not a matter of doubting everything, which would be paralysing, but of holding one''s views with a grip firm enough to act on and loose enough to revise."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m1-test-r3','c2-m1-test',13,'multiple_choice','reading','{"prompt":"What does intellectual humility mean here?","options":["Doubting everything","Holding views firmly enough to act but loosely enough to revise","Never expressing opinions"],"answer":1,"passage":{"title":"On the virtues of being wrong","text":"Seldom do we celebrate being wrong, and yet it is arguably the only route by which anyone has ever learnt anything. Science advances not by confirming what it already believes but by discovering, often to the considerable embarrassment of those concerned, that cherished theories do not survive contact with the evidence. Were individuals to adopt the same attitude, much needless conflict might be avoided. The difficulty is that being wrong rarely feels like anything at all until the moment we realise it; up to that point, it feels exactly like being right. Hence the peculiar confidence with which people defend positions they would, given more information, abandon without a second thought. Cultivating intellectual humility, then, is not a matter of doubting everything, which would be paralysing, but of holding one''s views with a grip firm enough to act on and loose enough to revise."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m2-test-r1','c2-m2-test',11,'multiple_choice','reading','{"prompt":"What risk of the plain English movement does the writer identify?","options":["Contracts becoming longer","Suspicion of any sentence that demands effort","Too many new words"],"answer":1,"passage":{"title":"The tyranny of plain English?","text":"Few causes command such universal assent as the campaign for plain English. Who, after all, would defend the impenetrable prose of insurance contracts or government circulars? And yet the enthusiasm for clarity can curdle into something more troubling: a suspicion of any sentence that asks the reader to work. Not all ideas are simple, and forcing complex arguments into short words and shorter sentences can distort them as surely as jargon obscures them. The philosopher who qualifies every claim is not necessarily evading responsibility; she may simply be accurate. The distinction worth drawing, then, is not between plain and difficult writing but between difficulty that is earned, because the subject demands it, and difficulty that is gratuitous, because the writer is careless, insecure or keen to impress. Clarity remains the goal; simplicity is only sometimes the means."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m2-test-r2','c2-m2-test',12,'multiple_choice','reading','{"prompt":"Why might the philosopher qualify every claim?","options":["To avoid responsibility","Because it is accurate","To impress readers"],"answer":1,"passage":{"title":"The tyranny of plain English?","text":"Few causes command such universal assent as the campaign for plain English. Who, after all, would defend the impenetrable prose of insurance contracts or government circulars? And yet the enthusiasm for clarity can curdle into something more troubling: a suspicion of any sentence that asks the reader to work. Not all ideas are simple, and forcing complex arguments into short words and shorter sentences can distort them as surely as jargon obscures them. The philosopher who qualifies every claim is not necessarily evading responsibility; she may simply be accurate. The distinction worth drawing, then, is not between plain and difficult writing but between difficulty that is earned, because the subject demands it, and difficulty that is gratuitous, because the writer is careless, insecure or keen to impress. Clarity remains the goal; simplicity is only sometimes the means."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m2-test-r3','c2-m2-test',13,'multiple_choice','reading','{"prompt":"What distinction does the writer propose?","options":["Plain vs difficult writing","Earned vs gratuitous difficulty","Formal vs informal style"],"answer":1,"passage":{"title":"The tyranny of plain English?","text":"Few causes command such universal assent as the campaign for plain English. Who, after all, would defend the impenetrable prose of insurance contracts or government circulars? And yet the enthusiasm for clarity can curdle into something more troubling: a suspicion of any sentence that asks the reader to work. Not all ideas are simple, and forcing complex arguments into short words and shorter sentences can distort them as surely as jargon obscures them. The philosopher who qualifies every claim is not necessarily evading responsibility; she may simply be accurate. The distinction worth drawing, then, is not between plain and difficult writing but between difficulty that is earned, because the subject demands it, and difficulty that is gratuitous, because the writer is careless, insecure or keen to impress. Clarity remains the goal; simplicity is only sometimes the means."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m3-test-r1','c2-m3-test',11,'multiple_choice','reading','{"prompt":"What is humorous about the thanks to the judges?","options":["The speaker never liked them","The speaker admires them more now that they''ve won","The judges were absent"],"answer":1,"passage":{"title":"Speech: accepting an award","text":"I''m conscious that the last thing anyone wants at this point in the evening is a long speech, so I''ll confine myself to three thank-yous and one confession. Thank you to the judges, whose judgement I have always admired and, as of tonight, admire rather more. Thank you to my team, who did most of the work while I did most of the worrying. And thank you to my family, who have heard more about supply chains over dinner than any family should have to. Now, the confession. When we started this project, I was fairly sure it would fail. That we''re here at all is less a tribute to my vision than to the stubbornness of people who refused to listen to me. If there''s a lesson in that, it''s perhaps this: surround yourself with people who are prepared to tell you you''re wrong, and then, occasionally, let them win."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m3-test-r2','c2-m3-test',12,'multiple_choice','reading','{"prompt":"What is the speaker''s confession?","options":["They didn''t do the project","They expected the project to fail","They wrote the speech that afternoon"],"answer":1,"passage":{"title":"Speech: accepting an award","text":"I''m conscious that the last thing anyone wants at this point in the evening is a long speech, so I''ll confine myself to three thank-yous and one confession. Thank you to the judges, whose judgement I have always admired and, as of tonight, admire rather more. Thank you to my team, who did most of the work while I did most of the worrying. And thank you to my family, who have heard more about supply chains over dinner than any family should have to. Now, the confession. When we started this project, I was fairly sure it would fail. That we''re here at all is less a tribute to my vision than to the stubbornness of people who refused to listen to me. If there''s a lesson in that, it''s perhaps this: surround yourself with people who are prepared to tell you you''re wrong, and then, occasionally, let them win."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m3-test-r3','c2-m3-test',13,'multiple_choice','reading','{"prompt":"What lesson does the speaker draw?","options":["Trust your own vision","Surround yourself with people willing to say you''re wrong","Work longer hours"],"answer":1,"passage":{"title":"Speech: accepting an award","text":"I''m conscious that the last thing anyone wants at this point in the evening is a long speech, so I''ll confine myself to three thank-yous and one confession. Thank you to the judges, whose judgement I have always admired and, as of tonight, admire rather more. Thank you to my team, who did most of the work while I did most of the worrying. And thank you to my family, who have heard more about supply chains over dinner than any family should have to. Now, the confession. When we started this project, I was fairly sure it would fail. That we''re here at all is less a tribute to my vision than to the stubbornness of people who refused to listen to me. If there''s a lesson in that, it''s perhaps this: surround yourself with people who are prepared to tell you you''re wrong, and then, occasionally, let them win."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m4-test-r1','c2-m4-test',11,'multiple_choice','reading','{"prompt":"What does the writer say about ''untranslatable'' words?","options":["They prove some feelings can''t exist in other languages","Their romance is often overstated","They should be avoided"],"answer":1,"passage":{"title":"Lost in translation, found in context","text":"Translators are fond of pointing out that some words have no exact equivalent: Portuguese ''saudade'', German ''Schadenfreude'', Danish ''hygge''. The romance of the untranslatable is seductive, but it can be overstated. English may lack a single word for ''saudade'', yet English speakers are perfectly capable of feeling and describing a bittersweet longing for something absent. What genuinely resists translation is less individual vocabulary than the web of associations a word carries: its register, its history, the jokes and songs it evokes. ''Mate'' and ''friend'' denote much the same relationship, but only one would sound natural in a Sydney pub. For the advanced learner, the challenge is therefore not to hunt for exotic words but to become sensitive to connotation, to sense, as a native speaker does, when a perfectly correct choice is nonetheless subtly wrong for the occasion."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m4-test-r2','c2-m4-test',12,'multiple_choice','reading','{"prompt":"What genuinely resists translation, according to the text?","options":["Grammar","The associations a word carries","Numbers"],"answer":1,"passage":{"title":"Lost in translation, found in context","text":"Translators are fond of pointing out that some words have no exact equivalent: Portuguese ''saudade'', German ''Schadenfreude'', Danish ''hygge''. The romance of the untranslatable is seductive, but it can be overstated. English may lack a single word for ''saudade'', yet English speakers are perfectly capable of feeling and describing a bittersweet longing for something absent. What genuinely resists translation is less individual vocabulary than the web of associations a word carries: its register, its history, the jokes and songs it evokes. ''Mate'' and ''friend'' denote much the same relationship, but only one would sound natural in a Sydney pub. For the advanced learner, the challenge is therefore not to hunt for exotic words but to become sensitive to connotation, to sense, as a native speaker does, when a perfectly correct choice is nonetheless subtly wrong for the occasion."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m4-test-r3','c2-m4-test',13,'multiple_choice','reading','{"prompt":"What is the main challenge for advanced learners?","options":["Learning exotic words","Becoming sensitive to connotation","Speaking faster"],"answer":1,"passage":{"title":"Lost in translation, found in context","text":"Translators are fond of pointing out that some words have no exact equivalent: Portuguese ''saudade'', German ''Schadenfreude'', Danish ''hygge''. The romance of the untranslatable is seductive, but it can be overstated. English may lack a single word for ''saudade'', yet English speakers are perfectly capable of feeling and describing a bittersweet longing for something absent. What genuinely resists translation is less individual vocabulary than the web of associations a word carries: its register, its history, the jokes and songs it evokes. ''Mate'' and ''friend'' denote much the same relationship, but only one would sound natural in a Sydney pub. For the advanced learner, the challenge is therefore not to hunt for exotic words but to become sensitive to connotation, to sense, as a native speaker does, when a perfectly correct choice is nonetheless subtly wrong for the occasion."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m5-test-r1','c2-m5-test',11,'multiple_choice','reading','{"prompt":"What is notably absent from the reference?","options":["Dates of employment","Any praise of the quality of his work","The company name"],"answer":1,"passage":{"title":"Reading between the lines of a reference","text":"To whom it may concern: I am pleased to confirm that Mr Daniel Hart was employed by our firm from 2019 to 2024. During this period he was invariably punctual, and his desk was always impeccably tidy. Mr Hart has a keen interest in a wide range of subjects, many of them unrelated to his duties, which he was always happy to discuss with colleagues at length. He approached every task with considerable enthusiasm, if not always with a clear sense of its purpose. I have no doubt that, in the right role, he would be an asset to any organisation. Should you require further information, I would be happy to provide it by telephone."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m5-test-r2','c2-m5-test',12,'multiple_choice','reading','{"prompt":"What does ''happy to discuss with colleagues at length'' most likely imply?","options":["He was a good communicator","He distracted colleagues with long conversations","He trained new staff"],"answer":1,"passage":{"title":"Reading between the lines of a reference","text":"To whom it may concern: I am pleased to confirm that Mr Daniel Hart was employed by our firm from 2019 to 2024. During this period he was invariably punctual, and his desk was always impeccably tidy. Mr Hart has a keen interest in a wide range of subjects, many of them unrelated to his duties, which he was always happy to discuss with colleagues at length. He approached every task with considerable enthusiasm, if not always with a clear sense of its purpose. I have no doubt that, in the right role, he would be an asset to any organisation. Should you require further information, I would be happy to provide it by telephone."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m5-test-r3','c2-m5-test',13,'multiple_choice','reading','{"prompt":"Why might the writer prefer to give further information by telephone?","options":["It''s faster","They may want to say things they won''t put in writing","They don''t use email"],"answer":1,"passage":{"title":"Reading between the lines of a reference","text":"To whom it may concern: I am pleased to confirm that Mr Daniel Hart was employed by our firm from 2019 to 2024. During this period he was invariably punctual, and his desk was always impeccably tidy. Mr Hart has a keen interest in a wide range of subjects, many of them unrelated to his duties, which he was always happy to discuss with colleagues at length. He approached every task with considerable enthusiasm, if not always with a clear sense of its purpose. I have no doubt that, in the right role, he would be an asset to any organisation. Should you require further information, I would be happy to provide it by telephone."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m6-test-r1','c2-m6-test',11,'multiple_choice','reading','{"prompt":"What might ''some very brave ideas'' really mean?","options":["Sincere admiration","A polite way of saying the proposal is unworkable","A request for more ideas"],"answer":1,"passage":{"title":"Politeness across cultures","text":"A British colleague who describes your proposal as ''interesting, with some very brave ideas'' may well be telling you, as politely as possible, that it is unworkable. Understatement and indirectness are deeply embedded in some varieties of English, and they routinely bewilder speakers from cultures where directness is considered a sign of honesty and respect. Neither style is inherently superior. What causes trouble is the assumption that one''s own conventions are simply ''normal''. A Brazilian manager who softens criticism with warmth and personal remarks may be seen as evasive in Amsterdam and perfectly judged in London; a Dutch colleague''s frank ''this won''t work'' may land as refreshing honesty or as startling rudeness depending on the listener. Competence in a language at the highest level, then, includes knowing not only what to say, but how much of it to leave unsaid."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m6-test-r2','c2-m6-test',12,'multiple_choice','reading','{"prompt":"What, according to the writer, causes trouble?","options":["Direct communication","Assuming one''s own conventions are simply normal","Understatement"],"answer":1,"passage":{"title":"Politeness across cultures","text":"A British colleague who describes your proposal as ''interesting, with some very brave ideas'' may well be telling you, as politely as possible, that it is unworkable. Understatement and indirectness are deeply embedded in some varieties of English, and they routinely bewilder speakers from cultures where directness is considered a sign of honesty and respect. Neither style is inherently superior. What causes trouble is the assumption that one''s own conventions are simply ''normal''. A Brazilian manager who softens criticism with warmth and personal remarks may be seen as evasive in Amsterdam and perfectly judged in London; a Dutch colleague''s frank ''this won''t work'' may land as refreshing honesty or as startling rudeness depending on the listener. Competence in a language at the highest level, then, includes knowing not only what to say, but how much of it to leave unsaid."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m6-test-r3','c2-m6-test',13,'multiple_choice','reading','{"prompt":"What does high-level competence include?","options":["Speaking very directly","Knowing how much to leave unsaid","Avoiding criticism"],"answer":1,"passage":{"title":"Politeness across cultures","text":"A British colleague who describes your proposal as ''interesting, with some very brave ideas'' may well be telling you, as politely as possible, that it is unworkable. Understatement and indirectness are deeply embedded in some varieties of English, and they routinely bewilder speakers from cultures where directness is considered a sign of honesty and respect. Neither style is inherently superior. What causes trouble is the assumption that one''s own conventions are simply ''normal''. A Brazilian manager who softens criticism with warmth and personal remarks may be seen as evasive in Amsterdam and perfectly judged in London; a Dutch colleague''s frank ''this won''t work'' may land as refreshing honesty or as startling rudeness depending on the listener. Competence in a language at the highest level, then, includes knowing not only what to say, but how much of it to leave unsaid."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m7-test-r1','c2-m7-test',11,'multiple_choice','reading','{"prompt":"What characterises the ''comfortable plateau''?","options":["Constant difficulty communicating","Good communication but no real improvement for years","Rapid progress"],"answer":1,"passage":{"title":"The illusion of fluency","text":"There is a stage in language learning that might be called the comfortable plateau. You can follow films, hold your own in meetings and rarely need a dictionary; yet, if you are honest, your English has not noticeably improved in years. The cause is seldom laziness. Rather, once communication succeeds, the pressure to refine it disappears: people understand you, so the slightly unnatural collocations and the handful of habitual errors go uncorrected. Escaping the plateau requires deliberately reintroducing difficulty. Recording yourself and comparing the transcript with how a highly proficient speaker would express the same ideas is humbling but revealing. So is writing in genres you never use, such as formal complaints, persuasive essays or speeches. Above all, it means asking for correction from people who will give it, since politeness, at this level, is the enemy of progress."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m7-test-r2','c2-m7-test',12,'multiple_choice','reading','{"prompt":"Why do errors go uncorrected at this stage?","options":["Communication succeeds, so there is no pressure to refine","Learners are lazy","Teachers are unavailable"],"answer":0,"passage":{"title":"The illusion of fluency","text":"There is a stage in language learning that might be called the comfortable plateau. You can follow films, hold your own in meetings and rarely need a dictionary; yet, if you are honest, your English has not noticeably improved in years. The cause is seldom laziness. Rather, once communication succeeds, the pressure to refine it disappears: people understand you, so the slightly unnatural collocations and the handful of habitual errors go uncorrected. Escaping the plateau requires deliberately reintroducing difficulty. Recording yourself and comparing the transcript with how a highly proficient speaker would express the same ideas is humbling but revealing. So is writing in genres you never use, such as formal complaints, persuasive essays or speeches. Above all, it means asking for correction from people who will give it, since politeness, at this level, is the enemy of progress."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m7-test-r3','c2-m7-test',13,'multiple_choice','reading','{"prompt":"Why is politeness called ''the enemy of progress''?","options":["People avoid correcting you","Polite language is less accurate","It wastes time"],"answer":0,"passage":{"title":"The illusion of fluency","text":"There is a stage in language learning that might be called the comfortable plateau. You can follow films, hold your own in meetings and rarely need a dictionary; yet, if you are honest, your English has not noticeably improved in years. The cause is seldom laziness. Rather, once communication succeeds, the pressure to refine it disappears: people understand you, so the slightly unnatural collocations and the handful of habitual errors go uncorrected. Escaping the plateau requires deliberately reintroducing difficulty. Recording yourself and comparing the transcript with how a highly proficient speaker would express the same ideas is humbling but revealing. So is writing in genres you never use, such as formal complaints, persuasive essays or speeches. Above all, it means asking for correction from people who will give it, since politeness, at this level, is the enemy of progress."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m8-test-r1','c2-m8-test',11,'multiple_choice','reading','{"prompt":"How many formats can students choose from?","options":["Two","Three","Four"],"answer":1,"passage":{"title":"Brief for a final project","text":"Your final project is an extended piece of work in English on a subject of genuine personal or professional interest. You may choose one of three formats: a 2,000-word report with recommendations, a 15-minute recorded presentation followed by questions, or a portfolio of shorter texts written for a real audience. Whatever the format, the project should demonstrate three things: the ability to handle complex ideas with precision, control of register appropriate to the intended readers or listeners, and the capacity to anticipate and respond to counter-arguments. You are encouraged to draw on sources, provided they are acknowledged, but the analysis must be your own. Assessment will focus less on the absence of errors than on the overall effectiveness of the communication. A brief proposal, no longer than one page, should be submitted before you begin."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m8-test-r2','c2-m8-test',12,'multiple_choice','reading','{"prompt":"Which of these must the project demonstrate?","options":["Perfect spelling","Responding to counter-arguments","Using at least ten sources"],"answer":1,"passage":{"title":"Brief for a final project","text":"Your final project is an extended piece of work in English on a subject of genuine personal or professional interest. You may choose one of three formats: a 2,000-word report with recommendations, a 15-minute recorded presentation followed by questions, or a portfolio of shorter texts written for a real audience. Whatever the format, the project should demonstrate three things: the ability to handle complex ideas with precision, control of register appropriate to the intended readers or listeners, and the capacity to anticipate and respond to counter-arguments. You are encouraged to draw on sources, provided they are acknowledged, but the analysis must be your own. Assessment will focus less on the absence of errors than on the overall effectiveness of the communication. A brief proposal, no longer than one page, should be submitted before you begin."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m8-test-r3','c2-m8-test',13,'multiple_choice','reading','{"prompt":"What will assessment mainly focus on?","options":["The absence of errors","The overall effectiveness of the communication","The length of the work"],"answer":1,"passage":{"title":"Brief for a final project","text":"Your final project is an extended piece of work in English on a subject of genuine personal or professional interest. You may choose one of three formats: a 2,000-word report with recommendations, a 15-minute recorded presentation followed by questions, or a portfolio of shorter texts written for a real audience. Whatever the format, the project should demonstrate three things: the ability to handle complex ideas with precision, control of register appropriate to the intended readers or listeners, and the capacity to anticipate and respond to counter-arguments. You are encouraged to draw on sources, provided they are acknowledged, but the analysis must be your own. Assessment will focus less on the absence of errors than on the overall effectiveness of the communication. A brief proposal, no longer than one page, should be submitted before you begin."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
